import{_ as o,o as t,c as d,a2 as a}from"./chunks/framework.vLhlLNVn.js";const m=JSON.parse('{"title":"How do I control covers, fans, locks and climate devices?","description":"","frontmatter":{"order":4,"adapter":"esphome","editLink":"https://github.com/DrozmotiX/ioBroker.esphome/edit/main/docs/en/03.referenz/04.cover-luefter-schloss-klima.md"},"headers":[],"relativePath":"adapter/esphome/referenz/cover-luefter-schloss-klima.md","filePath":"adapter/esphome/referenz/cover-luefter-schloss-klima.md","lastUpdated":1795571670000}'),i={name:"adapter/esphome/referenz/cover-luefter-schloss-klima.md"};function s(c,e,n,r,l,h){return t(),d("div",null,[...e[0]||(e[0]=[a(`<h1 id="how-do-i-control-covers-fans-locks-and-climate-devices" tabindex="-1">How do I control covers, fans, locks and climate devices? <a class="header-anchor" href="#how-do-i-control-covers-fans-locks-and-climate-devices" aria-label="Permalink to &quot;How do I control covers, fans, locks and climate devices?&quot;">​</a></h1><p><a id="control-covers-including-time-based"></a></p><h2 id="how-do-i-control-covers-including-time-based-position-tilt-stop" tabindex="-1">How do I control covers (including time_based): position, tilt, stop? <a class="header-anchor" href="#how-do-i-control-covers-including-time-based-position-tilt-stop" aria-label="Permalink to &quot;How do I control covers (including time_based): position, tilt, stop?&quot;">​</a></h2><p>A cover has the states <code>position</code>, <code>tilt</code> and <code>stop</code> under <code>esphome.0.&lt;device&gt;.Cover.&lt;key&gt;</code>. You read and write position and tilt in percent: <code>0</code> = closed, <code>100</code> = open.</p><table tabindex="0"><thead><tr><th>State</th><th>Values</th><th>Role</th></tr></thead><tbody><tr><td><code>position</code></td><td>0 to 100 %</td><td><code>level.blind</code></td></tr><tr><td><code>tilt</code></td><td>0 to 100 %</td><td><code>level.tilt</code></td></tr><tr><td><code>stop</code></td><td>any written value stops the cover</td><td><code>button</code></td></tr></tbody></table><p>There is no separate state for open or close, you write <code>100</code> or <code>0</code> to <code>position</code>. If your cover has no tilt, ignore <code>tilt</code>. VIS sliders and voice assistants for the role <code>level.blind</code> work without conversion.</p><h3 id="how-to-move-a-blind-to-a-position" tabindex="-1">How to move a blind to a position <a class="header-anchor" href="#how-to-move-a-blind-to-a-position" aria-label="Permalink to &quot;How to move a blind to a position&quot;">​</a></h3><ol><li>In admin, open the &quot;Objects&quot; tab and go to <code>esphome.0.&lt;device&gt;.Cover.&lt;key&gt;</code>.</li><li>Write the target value to <code>position</code>, e.g. <code>30</code> for 30 % open.</li><li>The device starts moving and reports its position back. The state then shows it confirmed (<code>ack = true</code>).</li><li>To stop, write <code>true</code> to <code>stop</code>.</li></ol><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setState</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;esphome.0.&lt;device&gt;.Cover.&lt;key&gt;.position&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">50</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setState</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;esphome.0.&lt;device&gt;.Cover.&lt;key&gt;.stop&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>If <code>position</code> always stays at 0, the device reports no position through the API. For <code>time_based</code> covers this depends on the YAML, the adapter only shows what arrives.</p><p><strong>See also:</strong> <a href="./../anleitungen/automatisieren#use-esphome-datapoints-aliases-alexa">Using states in aliases</a> · <a href="./datenpunkte#command-acknowledged-ack-happens-offline">When a command counts as confirmed</a> · <a href="./datenpunkte#datapoint-path-contain-number-instead">Why the path contains a number</a></p><p><a id="control-esphome-fan-speed-direction"></a></p><h2 id="how-do-i-control-an-esphome-fan-speed-direction-oscillation" tabindex="-1">How do I control an ESPHome fan (speed, direction, oscillation)? <a class="header-anchor" href="#how-do-i-control-an-esphome-fan-speed-direction-oscillation" aria-label="Permalink to &quot;How do I control an ESPHome fan (speed, direction, oscillation)?&quot;">​</a></h2><p>A fan has these states under <code>esphome.0.&lt;device&gt;.Fan.&lt;key&gt;</code>:</p><table tabindex="0"><thead><tr><th>State</th><th>Values</th><th>writable</th></tr></thead><tbody><tr><td><code>state</code></td><td><code>true</code> / <code>false</code></td><td>yes</td></tr><tr><td><code>speedLevel</code></td><td>1 to the number of levels</td><td>only with <code>speed_count</code> in the YAML</td></tr><tr><td><code>direction</code></td><td><code>0</code> forward, <code>1</code> reverse</td><td>only if the fan supports direction</td></tr><tr><td><code>oscillating</code></td><td><code>true</code> / <code>false</code></td><td>only if the fan can oscillate</td></tr><tr><td><code>speed</code></td><td>old speed value</td><td>no</td></tr></tbody></table><p>For the speed, write <code>speedLevel</code>. On every change the adapter sends all current values of the fan to the device together.</p><p><a id="operate-esphome-lock"></a></p><h2 id="how-do-i-operate-an-esphome-lock" tabindex="-1">How do I operate an ESPHome lock? <a class="header-anchor" href="#how-do-i-operate-an-esphome-lock" aria-label="Permalink to &quot;How do I operate an ESPHome lock?&quot;">​</a></h2><p>A lock has two states under <code>esphome.0.&lt;device&gt;.Lock.&lt;key&gt;</code>.</p><table tabindex="0"><thead><tr><th>State</th><th>Values</th></tr></thead><tbody><tr><td><code>state</code> (read-only)</td><td><code>0</code> unknown, <code>1</code> locked, <code>2</code> unlocked, <code>3</code> jammed, <code>4</code> locking, <code>5</code> unlocking</td></tr><tr><td><code>command</code></td><td><code>0</code> unlock, <code>1</code> lock, <code>2</code> open</td></tr></tbody></table><p>To operate it, write <code>command</code>. The state has no initial value, so nothing triggers by itself after a restart. <code>state</code> shows whether it worked.</p><p><a id="control-climate-device-example-midea"></a></p><h2 id="how-do-i-control-a-climate-device-for-example-a-midea-conversion" tabindex="-1">How do I control a climate device (for example a Midea conversion)? <a class="header-anchor" href="#how-do-i-control-a-climate-device-for-example-a-midea-conversion" aria-label="Permalink to &quot;How do I control a climate device (for example a Midea conversion)?&quot;">​</a></h2><p>A climate device works if it runs ESPHome with a <code>climate:</code> entity, e.g. the component <code>midea</code>, and the YAML contains <code>api:</code>. Then add it like any device with address and key. Without ESPHome firmware it does not work.</p><p>The states under <code>esphome.0.&lt;device&gt;.Climate.&lt;key&gt;</code> match the values the device reports, e.g. <code>mode</code>, <code>targetTemperature</code> and <code>fanMode</code>. All are writable except <code>currentTemperature</code>. Temperatures are in °C.</p><p>When you write a value, the adapter sends all current values of the device together. <code>mode</code> is a number from the ESPHome API, e.g. <code>0</code> off, <code>2</code> cool, <code>3</code> heat.</p>`,26)])])}const k=o(i,[["render",s]]);export{m as __pageData,k as default};
